solution.exercise.cpp:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool search(const domino *d, size_t n, bool *used, domino *out, size_t k,
                   int first, int last) {
    if (k == n)
        return first == last;
    for (size_t i = 0; i < n; i++)
        if (!used[i]) {
            for (int flip = 0; flip < 2; flip++) {
                int a = flip ? d[i].right : d[i].left,
                    b = flip ? d[i].left : d[i].right;
                if (k && a != last)
                    continue;
                used[i] = true;
                out[k].left = a;
                out[k].right = b;
                if (search(d, n, used, out, k + 1, k ? first : a, b))
                    return true;
                used[i] = false;
            }
        }
    return false;
}
bool chain(const domino *d, size_t n, domino *out) {
    if (!n)
        return true;
    bool *u = (bool *)calloc(n, sizeof(bool));
    bool ok = search(d, n, u, out, 0, 0, 0);
    free(u);
    return ok;
}

tests.test_exercise.cpp:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    domino a[] = {{1, 2}, {3, 1}, {2, 3}}, o[3];
    assert(chain(a, 3, o));
    for (int i = 0; i < 3; i++)
        assert(o[i].right == o[(i + 1) % 3].left);
    domino b[] = {{1, 2}, {2, 3}};
    assert(!chain(b, 2, o));
    assert(chain(NULL, 0, NULL));

    return 0;
}
